import json, glob, re, sys, os
sys.path.insert(0, "src")
from lypning import conformance as cf
from lypning.corpus import Entry

# Helper to safely sort a glob iterator by computing the list once.
def sorted_glob(path):
    return sorted(glob.glob(path, recursive=True))

n = 0
seeded = 0
sus = []

for f in sorted_glob("tests/corpus/**/*.jsonl"):
    for line in open(f):
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        p = o.get("program", "")
        if not cf._IMPORTS_RANDOM.search(p):
            continue
        n += 1
        e = Entry(id=o.get("id", "x"), program=p)
        if cf.is_seeded_stream(e):
            seeded += 1
            if re.search(r"seed\s*\(\s*(\)|None|[a-zA-Z_]\w*\s*\)", p) or "def seed" in p or re.search(r"seed\(\)", p):
                sus.append((f, p[:200]))

print("random programs:", n, "seeded:", seeded)
for f, p in sus:
    print("SUSPECT", f, repr(p))

