import re
import ast

def safe_eval(expr, allowed_chars=None):
    """Safely evaluate a string as a Python literal or expression using ast.literal_eval.

    Supports the patterns used in the test program by parsing and evaluating
    only safe constructs: strings, numbers, tuples, lists, dicts, sets, booleans,
    None, and basic arithmetic/expression evaluation.
    """
    # If ast.literal_eval can handle it directly, use that
    try:
        return ast.literal_eval(expr)
    except (ValueError, SyntaxError):
        pass

    # For re module function calls, we need custom handling
    # Parse the expression to understand its structure
    try:
        node = ast.parse(expr, mode='eval')
    except SyntaxError:
        return None

    # Walk the AST and evaluate only safe nodes
    result = _eval_node(node.body, set())
    return result


def _eval_node(node, allowed_ops):
    """Recursively evaluate an AST node, only allowing safe constructs."""
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        # Allow 're' module references
        if node.id == 're':
            return 're'
        return None
    elif isinstance(node, ast.Call):
        # Handle function calls
        func = _eval_node(node.func, allowed_ops)
        if func is None:
            return None

        # Handle re module calls
        if func == 're':
            args = [_eval_node(arg, allowed_ops) for arg in node.args]
            keywords = {kw.arg: _eval_node(kw.value, allowed_ops) for kw in node.keywords}

            # Map function names to implementations
            fname = None
            if isinstance(node.func, ast.Name):
                fname = node.func.id
            elif isinstance(node.func, ast.Attribute):
                fname = node.func.attr

            if fname == 'findall':
                if args and isinstance(args[0], str) and args[1] is not None:
                    pattern, string = args[0], args[1]
                    flags = keywords.get('flags', 0)
                    try:
                        return re.findall(pattern, string, flags)
                    except re.error:
                        return None
                return None
            elif fname == 'search':
                if args and isinstance(args[0], str) and args[1] is not None:
                    pattern, string = args[0], args[1]
                    flags = keywords.get('flags', 0)
                    try:
                        m = re.search(pattern, string, flags)
                        return m.group() if m else None
                    except re.error:
                        return None
                return None
            elif fname == 'match':
                if args and isinstance(args[0], str) and args[1] is not None:
                    pattern, string = args[0], args[1]
                    flags = keywords.get('flags', 0)
                    try:
                        m = re.match(pattern, string, flags)
                        return m.group() if m else None
                    except re.error:
                        return None
                return None
            elif fname == 'sub':
                if len(args) >= 2 and isinstance(args[0], str) and isinstance(args[1], str):
                    pattern, repl = args[0], args[1]
                    flags = keywords.get('flags', 0)
                    try:
                        return re.sub(pattern, repl, args[2] if len(args) > 2 else '', flags)
                    except re.error:
                        return None
                return None
            elif fname == 'split':
                if args and isinstance(args[0], str) and args[1] is not None:
                    pattern, string = args[0], args[1]
                    flags = keywords.get('flags', 0)
                    try:
                        return re.split(pattern, string, flags)
                    except re.error:
                        return None
                return None
            elif fname == 'compile':
                if args and isinstance(args[0], str):
                    flags = keywords.get('flags', 0)
                    try:
                        return re.compile(args[0], flags)
                    except re.error:
                        return None
                return None
            elif fname == 'escape':
                if args and isinstance(args[0], str):
                    try:
                        return re.escape(args[0])
                    except re.error:
                        return None
                return None
            elif fname == 'purge':
                return None
            elif fname == 'debug':
                return None
            else:
                return None
        return None
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand, allowed_ops)
        if operand is None:
            return None
        if isinstance(node.op, ast.Not):
            return not operand
        elif isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.USub):
            return -operand
        return None
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left, allowed_ops)
        right = _eval_node(node.right, allowed_ops)
        if left is None or right is None:
            return None
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.And):
            return left and right
        elif isinstance(node.op, ast.Or):
            return left or right
        return None
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left, allowed_ops)
        if left is None:
            return None
        # Handle comparisons like 'a > b', 'a == b', etc.
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval_node(comparator, allowed_ops)
            if right is None:
                return None
            if isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            else:
                return None
            left = result
        return left
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for value in node.values:
                evaluated = _eval_node(value, allowed_ops)
                if evaluated is None:
                    return None
                result = result and evaluated
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for value in node.values:
                evaluated = _eval_node(value, allowed_ops)
                if evaluated is None:
                    return None
                result = result or evaluated
            return result
        return None
    elif isinstance(node, ast.IfExp):
        # Ternary expression: x if condition else y
        test = _eval_node(node.test, allowed_ops)
        if test is None:
            return None
        if test:
            return _eval_node(node.body, allowed_ops)
        else:
