import sys, re

def extract_words(text):
    """Extract contiguous ASCII word characters from text, ignoring non-ASCII."""
    words = []
    current = []
    for ch in text:
        # Only ASCII letters, digits, and underscore count as word chars
        code = ord(ch)
        if (0x30 <= code <= 0x39) or (0x41 <= code <= 0x5A) or (0x61 <= code <= 0x7A) or code == 0x5F:
            current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    return words

if __name__ == '__main__':
    input_text = sys.stdin.read()
    result = extract_words(input_text)
    print(result)

import sys

def ascii_word_split(text):
    """Split text into contiguous ASCII word tokens using only plain builtins."""
    words = []
    current = []
    for ch in text:
        code = ord(ch)
        # ASCII letters, digits and underscore count as word characters
        if 48 <= code <= 57 or 65 <= code <= 90 or 97 <= code <= 122:
            current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    return words

