import sys

# Manually replace all non-alphanumeric ASCII characters with '-'
# to avoid the \W/Unicode issue in this runtime.
s = "Kalle Anka på Öland!"
out = []
for ch in s:
    # ord < 128 ensures we stay in pure ASCII range;
    # ch.isalnum() checks alphanumeric in that ASCII subspace.
    if ord(ch) < 128 and ch.isalnum():
        out.append(ch)
    else:
        out.append('-')
print(''.join(out))

import os

def is_alpha_numeric_ascii(c):
    """Return True if character is ASCII letter or digit."""
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')

def main():
    s = "Kalle Anka på Öland!"
    # Manually replace any non-ASCII-alphanumeric sequence with '-'
    result = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if is_alpha_numeric_ascii(c):
            result.append(c)
            i += 1
        else:
            # Replace the maximal contiguous run of non-alphanumeric ASCII chars with a single '-'
            result.append('-')
            while i < n and not is_alpha_numeric_ascii(s[i]):
                i += 1
    print(''.join(result))

if __name__ == '__main__':
    main()

