# map validate flag: the engine only accepts False/None/0, any truthy value must
# select strict mode but we cannot pass strict=… directly to b64decode.
# We therefore handle the two cases manually.
def safe_b64decode(data, validate):
    if validate:
        # strict mode: reject anything that is not valid base64.
        # binascii.a2b_base64 with strict_mode=True raises binascii.Error on failure.
        return binascii.a2b_base64(data, strict_mode=True)
    else:
        # non‑strict mode: accept flawed input and let base64 module handle it.
        return base64.b64decode(data, validate=False)

