import json, glob, collections, os

root = os.path.expanduser("~/.claude/projects")
per = collections.defaultdict(collections.Counter)
side = collections.Counter()
n = 0
for f in sorted(glob.glob(root + "/*/*.jsonl")):
    n += 1
    try:
        fh = open(f)
    except OSError:
        continue
    with fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except Exception:
                continue
            m = ev.get('message')
            if isinstance(m, dict) and isinstance(m.get('model'), str):
                per[os.path.basename(f)][m['model']] += 1
                if ev.get('isSidechain'):
                    side[m['model']] += 1
print("transcript files scanned:", n)
multi = [(k, dict(v)) for k, v in per.items() if len([x for x in v if x != '<synthetic>']) > 1]
print("sessions with >1 real model:", len(multi), "of", len(per))
for k, v in multi[:10]:
    print(" ", k, v)
allm = collections.Counter()
for v in per.values():
    allm.update(v)
print("all models:", allm.most_common(12))
print("sidechain models:", side.most_common(6))

