import sys

# Mapping from built-in type names to the actual types
TYPES = {
    "int": int,
    "float": float,
    "str": str,
    "bool": bool,
}

# Operators mapping
OPERATORS = {
    "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b,
    ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
    "==": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
}

# Literal parser
def parse_literal(s):
    """Parse a string literal to its Python value."""
    if s == "''" or s == '"':
        return ""
    if s == "None":
        return None
    if s == "True":
        return True
    if s == "False":
        return False
    # Numeric literals
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        pass
    # Already handled above, but just in case
    return s


def evaluate_expression(expr):
    """Safely evaluate a simple comparison or expression from the given string."""
    # Split the expression into left, operator, right
    # We need to handle cases like "float('nan')" which contain parentheses
    # Strategy: find the operator that splits the expression

    # First, handle the special case of float('nan') which has parentheses
    # We'll use a simple approach: try to parse by finding the operator

    # Remove any outer whitespace
    expr = expr.strip()

    # Try to match operators, being careful with float('nan') etc.
    # We'll scan for operators from right to left to handle cases like a < b < c (though not in our cases)

    # List of operators sorted by length descending
    sorted_ops = sorted(OPERATORS.keys(), key=len, reverse=True)

    found_op = None
    op_pos = -1

    for op in sorted_ops:
        # Find the position of the operator
        # We need to be careful not to match inside function calls
        # Simple approach: find all occurrences and check context
        pos = expr.find(op)
        while pos != -1:
            # Check if this operator is at the "comparison level"
            # For simplicity, we'll just take the first reasonable match
            # In our test cases, operators appear between two main expressions
            if found_op is None or pos < op_pos:
                # Basic check: make sure we're not inside parentheses
                # Count parentheses before this position
                before = expr[:pos]
                if before.count('(') == before.count(')'):
                    found_op = op
                    op_pos = pos
                    # Don't break, check if there's a better (earlier) match
            # Look for next occurrence
            pos = expr.find(op, pos + 1)
            if found_op is not None and pos > op_pos:
                break  # We already found an earlier one

    if found_op is None:
        # Could not parse, return the string
        return expr

    # Split into left and right parts
    left_str = expr[:op_pos].strip()
    right_str = expr[op_pos + len(found_op):].strip()

    # Parse left and right
    try:
        left = parse_literal(left_str)
    except Exception:
        left = left_str

    try:
        right = parse_literal(right_str)
    except Exception:
        right = right_str

    # Apply operator
    if found_op in OPERATORS:
        try:
            result = OPERATORS[found_op](left, right)
            return result
        except Exception as e:
            return f"{type(e).__name__}: {e}"
    else:
        return f"Unknown operator: {found_op}"


def main():
    CASES = [
        "0 <= ''", "0 > ''", "[1] < ['a']", "[1] <= ['a']", "[1] >= ['a']", "[1] > ['a']",
        "(1,) > ('a',)", "[float('nan')] < [1.0]", "[float('nan')] <= [1.0]",
        "[1.0] < [float('nan')]", "float('nan') < 1", "float('nan') <= 1",
