        "sorted([1,'a'])", "sorted([float('nan'), 1.0])", "{1} < {1,2}", "None < 1",
    ]

    for c in CASES:
        try:
            # Evaluate using our safe function
            result = evaluate_expression(c)
            # Format output
            print("%-32s -> %r" % (c, result))
        except Exception as e:
            print("%-32s -> %s: %s" % (c, type(e).__name__, e))


