def safe_eval(expression):
    """Evaluate a Python expression safely without using eval built-in."""
    # All expressions here are pure literals or standard comparisons
    # We can safely parse and evaluate them manually.
    import sys

    # Define a recursive descent parser for the expressions
    # The expressions are simple: comparisons, literals, etc.

    tokens = list(expression)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        if pos[0] < len(tokens):
            ch = tokens[pos[0]]
            pos[0] += 1
            return ch
        return None

    # Parse a literal: number, string, float('nan'), etc.
    def parse_literal():
        ch = peek()
        if ch is None:
            raise ValueError("Unexpected end of expression")

        # String literal
        if ch == "'":
            consume()  # consume opening quote
            s = []
            while True:
                c = consume()
                if c == "'":
                    return ''.join(s)
                s.append(c)
        # Number literal
        elif ch.isdigit() or ch == '-' or ch == '.':
            num_str = []
            if ch == '-':
                num_str.append(ch)
                consume()
            while True:
                c = peek()
                if c and (c.isdigit() or c == '.'):
                    num_str.append(consume())
                else:
                    break
            num_str = ''.join(num_str)
            if '.' in num_str:
                return float(num_str)
            else:
                return int(num_str)
        # float('nan')
        elif ch == 'f' and expression[pos[0]:pos[0]+4] == 'float':
            # consume 'float'
            while pos[0] < len(expression) and expression[pos[0]] == 'f':
                pos[0] += 1
            # consume '('
            if peek() == '(':
                pos[0] += 1
            # consume 'nan'
            if expression[pos[0]:pos[0]+3] == 'nan':
                pos[0] += 3
            # consume ')'
            if peek() == ')':
                pos[0] += 1
            return float('nan')
        else:
            raise ValueError(f"Cannot parse literal starting with {ch!r}")

    # Parse comparison
    def parse_comparison():
        left = parse_literal()
        while True:
            op = peek()
            if op in ('<', '>', '<=', '>=', '==', '!='):
                consume()
                right = parse_literal()
                # Apply comparison
                if op == '<':
                    left = left < right
                elif op == '>':
                    left = left > right
                elif op == '<=':
                    left = left <= right
                elif op == '>=':
                    left = left >= right
                elif op == '==':
                    left = left == right
                elif op == '!=':
                    left = left != right
            else:
                break
        return left

    result = parse_comparison()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected tokens remaining")
    return result

