            return node.value
        if isinstance(node, ast.Name):
            if node.id in allowed_names:
                return allowed_names[node.id]
            raise NameError(f"Name {node.id!r} is not allowed")
        if isinstance(node, ast.UnaryOp):
            return OPS[type(node.op)](_eval_node(node.operand))
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for v in node.values:
                    result = result and _eval_node(v)
                    if not result:
                        return result
                return result
            elif isinstance(node.op, ast.Or):
                result = False
                for v in node.values:
                    result = result or _eval_node(v)
                    if result:
                        return result
                return result
        if isinstance(node, ast.Compare):
            left = _eval_node(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = _eval_node(comparator)
                if not OPS[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.BinOp):
            return OPS[type(node.op)](_eval_node(node.left), _eval_node(node.right))
        # Disallow anything else
        raise TypeError(f"Unsupported AST node: {type(node).__name__}")

    # Parse expression string to AST; if it contains statements, compile will fail.
    try:
        tree = compile(expr, '<string>', 'eval')
    except SyntaxError:
        # Fallback: try to evaluate using the restricted approach below.
        # But first, we must not use eval. We'll use a simple split/eval for literals only.
        # Actually, we can just use eval with restricted globals here as last resort,
        # but the spec says no eval. So we raise.
        raise ValueError(f"Cannot parse expression: {expr!r}")

    # Validate the AST contains only safe nodes
    # We'll do a quick check: no imports, no function calls, etc.
    # Since we compile with 'eval', it should be an expression only.
    # Now evaluate.
    try:
        return _eval_node(tree)
    except Exception as e:
        raise e

