# Simulated eval for byte string methods
# This replicates the behavior of eval("b'abc'.%s(%s)" % (m, b))
# without using the eval builtin.

METHODS = ["find","rfind","index","rindex","count","split","rsplit","startswith",
           "endswith","join","partition","rpartition","strip","lstrip","rstrip",
           "replace","removeprefix","removesuffix"]
BADS = ["1","'a'","[97]","(97,)", "None", "97"]
seen = {}

def eval_byte_method(expr):
    """
    Parse expr of the form "b'...'.method(args)" and return the result,
    or raise the exception that eval would raise.
    """
    # Split on the first '.' to get the byte string and the rest
    dot = expr.index('.')
    bs_str = expr[:dot]          # e.g. "b'abc'"
    rest = expr[dot+1:]          # e.g. "find('a')"

    # Parse the byte string literal b'...'
    # We expect exactly: b'...'  (single quotes inside)
    if not (bs_str.startswith("b'") and bs_str.endswith("'")):
        raise ValueError("not a byte string literal: %s" % bs_str)
    inner = bs_str[2:-1]         # strip b' and '
    byte_val = bytes(inner, "ascii")

    # Now parse rest: method_name(args)
    # Find the method name (up to '(')
    paren = rest.index('(')
    method_name = rest[:paren]
    args_str = rest[paren+1:]    # everything between '(' and ')'

    # Find matching ')' to extract argument text
    # Simple approach: find the first ')' that is not inside nested parens?
    # For safety, we just find the first ')'.
    # But args could contain nested parens (e.g., replace with count).
    # We'll use a count balance.
    balance = 1
    i = 0
    while i < len(args_str) and balance > 0:
        ch = args_str[i]
        if ch == '(':
            balance += 1
        elif ch == ')':
            balance -= 1
        i += 1
    # i is one past the matching ')'
    args_text = args_str[:i-1]   # up to and including the matching ')'
    # Actually we want the content between '(' and the matching ')'
    # Let's recalculate:
    # args_text should be the string inside the outer parentheses.
    # We'll just take everything between the first '(' and the matching ')'.
    # Re-parse carefully:
    start = rest.index('(')
    # find matching ')'
    bal = 1
    j = start + 1
    while j < len(rest) and bal > 0:
        if rest[j] == '(':
            bal += 1
        elif rest[j] == ')':
            bal -= 1
        j += 1
    # j is one past the matching ')'
    args_inner = rest[start+1:j-1]  # content between parentheses

    # Now dispatch by method_name on byte_val
    # We need to handle the arguments appropriately.
    # For simplicity, we will try to convert args to appropriate types.
    # But we must exactly match eval behavior.

    # Let's just use getattr and call with parsed args.
    # We'll parse args_inner into Python objects.

    # Helper to parse a simple argument:
    # It could be a string literal '...', a number, None, a list/tuple of numbers, etc.
    def parse_arg(s):
        s = s.strip()
        if not s:
            return None
        # String literal '...'
        if s.startswith("'") and s.endswith("'"):
            return s[1:-1]
        # maybe "b'...'"?
        if s.startswith("b'") and s.endswith("'"):
            return bytes(s[2:-1], "ascii")
        # None
        if s == "None":
            return None
        # integer
        try:
            return int(s)
        except ValueError:
            pass
        # float
        try:
            return float(s)
        except ValueError:
            pass
        # Maybe a list like [97] or (97,)
        if s.startswith('[') and s.endswith(']'):
            inner = s[1:-1]
            # split by commas, but be careful with nested?
            # For simplicity, assume flat list of integers
            items = [x.strip() for x in inner.split(',') if x.strip()]
            return [int(x) for x in items]
        if s.startswith('(') and s.endswith(')'):
            inner = s[1:-1]
            items = [x.strip() for x in inner.split(',') if x.strip()]
            return tuple(int(x) for x in items)
        # If all else fails, return as string (might cause error later)
        return s

    # Parse arguments list: args_inner could be empty, or comma-separated
    if not args_inner.strip():
        args = []
    else:
        # split by commas, but respect parentheses? For simplicity, assume no nested commas
        # Actually we should split carefully. We'll just split by commas at top level.
        # Since our BADS are simple, this should be fine.
        parts = []
        bal2 = 0
        current = []
        for ch in args_inner:
            if ch == '(':
                bal2 += 1
                current.append(ch)
            elif ch == ')':
                bal2 -= 1
                current.append(ch)
            elif ch == ',' and bal2 == 0:
                parts.append(''.join(current))
                current = []
            else:
                current.append(ch)
        if current:
            parts.append(''.join(current))
        args = [parse_arg(p) for p in parts]

    # Now get the method
    if not hasattr(byte_val, method_name):
        raise AttributeError("byte string has no attribute %s" % method_name)
    method = getattr(byte_val, method_name)

    # Call the method with args
    try:
        return method(*args)
    except Exception as e:
        raise e

