    print('Q1', {1,2} in s)
except Exception as e:
    print('Q1 EXC', type(e).__name__, str(e))
try:
    print('Q2', [1,2] in s)
except Exception as e:
    print('Q2 EXC', type(e).__name__, str(e))
s2 = {set([1,2]), set([3])}
try:
    s2.discard({1,2})
    print('Q3', len(s2))
except Exception as e:
    print('Q3 EXC', type(e).__name__, str(e))
s3 = {set([1,2])}
try:
    s3.remove({1,2})
    print('Q4', len(s3))
except Exception as e:
    print('Q4 EXC', type(e).__name__, str(e))
try:
    print('Q5', {1,2} in {'a':1})
except Exception as e:
    print('Q5 EXC', type(e).__name__, str(e))
