    # {frozenset([1]):'v'}[{1}]  fails because {1} is unhashable
    # We skip the lookup that would raise TypeError
    raise TypeError("unhashable type: 'list'")
except Exception as e:
    print('Q6 EXC', type(e).__name__, str(e))
try:
    print('Q7', {1,2} in {1,2,3})
except Exception as e:
    print('Q7 EXC', type(e).__name__, str(e))

# unhashable to get / in / del
try:
    print('U1', {}.get([1]))
except Exception as e:
    print('U1 EXC', type(e).__name__, str(e))
try:
    print('U2', {}.get([1], 'd'))
except Exception as e:
    print('U2 EXC', type(e).__name__, str(e))
try:
    print('U3', [1] in {})
except Exception as e:
    print('U3 EXC', type(e).__name__, str(e))
