# --- Q1 / Q2 : set/frozenset auto-conversion quirk ---
# Original: s = {frozenset([1,2])}
# Checking {1,2} in s uses hash of frozenset (which equals hash of the tuple of sorted items)
# Checking [1,2] in s raises TypeError because list is unhashable.
# We simulate by using a set of tuples.
s = {([1, 2],)}  # tuple represents the frozenset contents
try:
    # {1,2} in s: set membership with another set. {1,2} is unhashable -> TypeError
    print('Q1', {1, 2} in s)
except Exception as e:
    print('Q1 EXC', type(e).__name__, str(e))
try:
    # [1,2] in s: list is unhashable -> TypeError
    print('Q2', [1, 2] in s)
except Exception as e:
    print('Q2 EXC', type(e).__name__, str(e))

# --- Q3 : discard with set argument ---
# Original: s2 = {frozenset([1,2]), frozenset([3])}; s2.discard({1,2})
# discard with a set argument: sets are unhashable, so discard raises TypeError.
# We simulate s2 as a set of tuples.
s2 = {([1, 2],), ([3],)}
try:
    s2.discard({1, 2})
    print('Q3', len(s2))
except Exception as e:
    print('Q3 EXC', type(e).__name__, str(e))

