import os
import sys

def my_quote(s, safe=''):
    """Mimics urllib.parse.quote with safe='' (default)."""
    # Characters that are always safe (not percent-encoded):
    # letters, digits, and the characters : / ? @ ! $ & ' ( ) * + , ; = -
    # When safe='' the default safe string '/' is removed.
    safe_default = '/'
    # Build the set of characters to not encode.
    if safe == '':
        # Remove '/' from the default safe set
        forbid = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
                     ' :/?@!$&\'()*+,;=-') - {safe_default}
    else:
        forbid = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
                     ' :/?@!$&\'()*+,;=-') | set(safe)
    # Encode any character not in the allowed set.
    result = []
    for ch in s:
        if ch in forbid:
            result.append(ch)
        else:
            result.append('%' + format(ord(ch), '02X'))
    return ''.join(result)


def my_unquote(s):
    """Mimics urllib.parse.unquote."""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i+1:i+3]
            try:
                ch = chr(int(hex_str, 16))
                result.append(ch)
                i += 3
                continue
            except ValueError:
                pass
        result.append(s[i])
        i += 1
    return ''.join(result)


def my_urlencode(query, doseq=False):
    """Mimics urllib.parse.urlencode for simple key-value pairs."""
    parts = []
    for k, v in query.items():
        parts.append(my_quote(str(k)) + '=' + my_quote(str(v)))
    return '&'.join(parts)


# Produce the same output as the original program.
print(my_quote("a b/c?"), my_quote("a b/c?", safe=""), my_unquote("a%20b"), my_urlencode({"q": "x y", "n": 2}))

import os, sys

def quote(s, safe=''):
    """Rough implementation of urllib.parse.quote for the specific patterns used."""
    # Characters that are never quoted unless they appear in the string
    unreserved = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~')
    result = []
    for ch in s:
        if ch in unreserved:
            result.append(ch)
        else:
            # Percent-encode the character
            hex_val = format(ord(ch), '02X')
            result.append('%' + hex_val)
    return ''.join(result)

def unquote(s):
    """Rough implementation of urllib.parse.unquote for the specific pattern used."""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i+1:i+3]
            # Validate hex digits
            try:
                byte_val = int(hex_str, 16)
                result.append(chr(byte_val))
                i += 3
                continue
            except ValueError:
                pass
        result.append(s[i])
        i += 1
    return ''.join(result)

def urlencode(params):
    """Rough implementation of urllib.parse.urlencode for the specific pattern used."""
    parts = []
    for key, value in params.items():
        # key and value are encoded using quote with safe=''
        encoded_key = quote(str(key), safe='')
        encoded_value = quote(str(value), safe='')
        parts.append(encoded_key + '=' + encoded_value)
    return '&'.join(parts)

