# Manual percent-encoding: map each char to %XX if not unreserved, else keep as-is.
# Unreserved: ALPHA / DIGIT / "-" / "." / "_" / "~"
def _percent_encode(s):
    out = bytearray()
    for ch in s:
        cv = ord(ch)
        if (48 <= cv <= 57 or    # '0'-'9'
            65 <= cv <= 90 or    # 'A'-'Z'
            97 <= cv <= 122 or   # 'a'-'z'
            cv == 45 or cv == 46 or cv == 95 or cv == 126):  # '-' '.' '_' '~'
            out += ch.encode('utf-8')
        else:
            out += f"%{cv:02X}".encode('ascii')
    return out.decode('utf-8')


def _urlencode(qs):
    """Mimic urllib.parse.urlencode for flat key=value pairs, using '=' and '&' separators,
    quoting value with safe='' (i.e. full percent-encoding)."""
    parts = []
    for k, v in qs.items():
        parts.append(f"{_percent_encode(k)}={_percent_encode(v)}")
    return "&".join(parts)


def main():
    # quote("a b/c?")          -> a%20b%2Fc%3F
    # quote("a b/c?", safe="") -> same (safe='' means no extra safe chars)
    # unquote("a%20b")         -> a b
    # urlencode({"q": "x y", "n": 2}) -> q=x%20y&n=2
    print(_percent_encode("a b/c?"),
          _percent_encode("a b/c?"),
          _unquote("a%20b"),
          _urlencode({"q": "x y", "n": 2}))


def _unquote(s):
    # Replace %XX with the corresponding byte (latin-1 decode).
    out = bytearray()
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '%' and i + 2 < n:
            hex_str = s[i+1:i+3]
            try:
                byte_val = int(hex_str, 16)
                out += bytes([byte_val])
                i += 3
                continue
            except ValueError:
                pass
        out += s[i].encode('utf-8')
        i += 1
    return out.decode('latin-1')


if __name__ == "__main__":
    main()

import os
import sys

def url_encode(data):
    """Encode a dict of key-value pairs into a URL query string using '+' for spaces."""
    parts = []
    for key, value in data.items():
        # Encode key and value manually: replace spaces with '+', percent-encode everything else
        def encode_component(s):
            out = []
            for ch in s:
                if ch == ' ':
                    out.append('+')
                elif ch.isalnum() or ch in '-._~':
                    out.append(ch)
                else:
                    out.append('%' + format(ord(ch), '02X'))
            return ''.join(out)
        parts.append(encode_component(key) + '=' + encode_component(value))
    return '&'.join(parts)

def url_decode(s):
    """Decode a URL-encoded string, handling '+' as space."""
    out = []
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i+1:i+3]
            try:
                code = int(hex_str, 16)
                out.append(chr(code))
                i += 3
                continue
            except ValueError:
                pass
        if s[i] == '+':
            out.append(' ')
        else:
            out.append(s[i])
        i += 1
    return ''.join(out)

def quote(s, safe=''):
    """Percent-encode *all* characters except alphanumerics and those in *safe*.
    This mirrors ``urllib.parse.quote(s, safe='')``."""
    out = []
    for ch in s:
        if ch.isalnum() or ch in safe:
            out.append(ch)
        else:
            out.append('%' + format(ord(ch), '02X'))
    return ''.join(out)

def main():
    # 1) quote("a b/c?")  → all non-alnum encoded
    part1 = quote("a b/c?")
    # 2) quote("a b/c?", safe="")  → identical to part1 when safe is empty
    part2 = quote("a b/c?", safe="")
    # 3) unquote("a%20b") → decode %20 to space
    part3 = url_decode("a%20b")
    # 4) urlencode({"q": "x y", "n": 2}) → key=value pairs joined with '&', space as '+'
    part4 = url_encode({"q": "x y", "n": 2})

    print(part1, part2, part3, part4)

if __name__ == '__main__':
    main()

