# Manually implement quote, unquote, urlencode from urllib.parse without importing it

def _quote(s, safe=''):
    """String quote exactly as urllib.parse.quote does, using /./ for unreserved."""
    # RFC 3986 unreserved: A-Z a-z 0-9 - . _
    _unreserved = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.')
    # Additionally, quote always keeps these chars unescaped besides the ones in safe:
    # The default safe='' but we pass safe explicitly.
    out = []
    for ch in s:
        if ch in _unreserved or ch in safe:
            out.append(ch)
        else:
            # Encode as %HH using UTF-8 bytes
            for b in ch.encode('utf-8'):
                out.append('%' + format(b, '02X'))
    return ''.join(out)


def _unquote(s):
    """String unquote exactly as urllib.parse.unquote does."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '%' and i + 2 < n:
            hex_str = s[i+1:i+3]
            try:
                byte_val = int(hex_str, 16)
                out.append(chr(byte_val))
                i += 3
                continue
            except ValueError:
                pass
        out.append(s[i])
        i += 1
    return ''.join(out)


def _urlencode(query, doseq=False):
    """Dict urlencode exactly as urllib.parse.urlencode does (basic, no quotes)."""
    parts = []
    for key, value in query.items():
        if doseq and isinstance(value, list):
            for item in value:
                parts.append(_quote(str(key)) + '=' + _quote(str(item)))
        else:
            parts.append(_quote(str(key)) + '=' + _quote(str(value)))
    return '&'.join(parts)


