import sys, os

def url_encode(params):
    result = []
    first = True
    for key, val in params.items():
        if not first:
            result.append('&')
        else:
            first = False
        # Simple encoding: replace spaces with '+', '=' with '%3D', '&' with '%26'
        def esc(s):
            s = s.replace(' ', '+')
            s = s.replace('=', '%3D')
            s = s.replace('&', '%26')
            return s
        result.append(esc(str(key)) + '=' + esc(str(val)))
    return ''.join(result)

def url_unquote(s):
    # Decode %XX sequences, replace '+' with space
    import re
    def _decode_match(m):
        hex_val = m.group(1)
        return chr(int(hex_val, 16))
    s = re.sub(r'%([0-9A-Fa-f]{2})', _decode_match, s)
    s = s.replace('+', ' ')
    return s

def simple_quote(s, safe=''):
    # Minimal quoting: escape ' ' and control characters if not in safe set
    result = []
    for ch in s:
        if ch in safe or (ch.isalnum() or ch in '.-_~'):
            result.append(ch)
        elif ch == ' ':
            result.append('%20')
        elif ord(ch) < 0x20 or ord(ch) > 0x7E:
            result.append('%' + format(ord(ch), '02X'))
        else:
            # Escape other unreserved chars
            result.append('%' + format(ord(ch), '02X'))
    return ''.join(result)

