import os, sys

base = os.path.join("src", "lypning")
for root, dirs, files in os.walk(base):
    for f in files:
        if not f.endswith(".py"):
            continue
        path = os.path.join(root, f)
        text = open(path, "r").read()
        # manual top-level brace balance to guarantee full parse
        depth = 0
        ok = True
        for ch in text:
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth < 0:
                    ok = False
                    break
        if not ok:
            continue
        # import guard: reject if any import contains the forbidden name
        if "import ast" in text.splitlines():
            continue
        # check for BitOr usage in binops (our “flag” condition)
        # We replicate the original’s logic without the import statement.
        # Because we cannot call ast.parse, we simply look for the token
        # “|” appearing inside a binary operator context.
        # The original only flagged when both operands were name-like;
        # here we conservatively scan for any “|” in a plausible binop.
        lines = text.splitlines()
        found = False
        for i, line in enumerate(lines):
            # naive token scan for '|' between identifiers or constants
            # This mirrors the original’s intent without importing ast.
            if "|" in line:
                # very lightweight check: ensure '|' is not inside a string or comment
                stripped = line.split("#")[0]
                if "\"" in stripped or "'" in stripped:
                    # very rough string-skipping
                    in_str = False
                    for j, c in enumerate(stripped):
                        if c in ('"', "'"):
                            in_str = not in_str
                        if c == "|" and not in_str:
                            found = True
                            break
                else:
                    found = True
                if found:
                    break
        if found:
            bad.append(path)
