    """Return a list of file paths as returned by `git ls-files`, or []."""
    try:
        result = os.popen('git ls-files').read()
        if not result.strip():
            return []
        # The original program splits on '\n' and keeps empty strings,
        # but we filter them out later (the `if not f: continue` guard).
        return result.split('\n')
    except Exception:
        return []


