    for f in files:
        if not f or f.startswith('public/introspect/'):
            continue
        try:
            with open(f, 'rb') as fh:
                b = fh.read()
        except Exception:
            continue
        if dec in b:
            hits['decomposed'].append(f)
        if pre in b:
            hits['precomposed'].append(f)
        if plain in b:
            hits['plain'].append(f)

    for k, v in hits.items():
        # Print exactly as the reference does: field width 14, right-aligned,
