import argparse, inspect

# Replicate the _AttributeHolder class exactly as argparse defines it
class _AttributeHolder:
    __slots__ = ('_args',)

    def __init__(self, args):
        self._args = args

    def __getattr__(self, name):
        return getattr(self._args, name)

    def __setattr__(self, name, value):
        if name == '_args':
            super().__setattr__(name, value)
        else:
            setattr(self._args, name, value)

    def __delattr__(self, name):
        if name == '_args':
            super().__delattr__(name)
        else:
            delattr(self._args, name)

# Instantiate and print its source
holder = _AttributeHolder(argparse.ArgumentParser())
print(inspect.getsource(_AttributeHolder))

import os, sys

def which(cmd):
    """Emulate shutil.which logic using only os.path."""
    if os.path.isabs(cmd):
        if os.path.exists(cmd) and os.access(cmd, os.X_OK):
            return cmd
        return None
    # Search PATH
    path = os.environ.get("PATH", os.defpath)
    for dirpath in path.split(os.pathsep):
        full = os.path.join(dirpath, cmd)
        if os.path.exists(full) and os.access(full, os.X_OK):
            return full
    return None

