import os, sys

def which(program):
    """Replicate shutil.which without importing shutil."""
    if not program:
        return None

    # Use the existing PATH from the environment
    path_str = os.environ.get("PATH", os.defpath)
    path_dirs = path_str.split(os.pathsep)

    # Determine if the program already contains a path separator
    if os.sep in program:
        # Absolute or relative path
        if os.path.isfile(program) and os.access(program, os.X_OK):
            return program
        return None

    # Search through PATH directories
    for path in path_dirs:
        full_path = os.path.join(path, program)
        if os.path.isfile(full_path) and os.access(full_path, os.X_OK):
            return full_path

    return None


