import os, sys

def which(cmd):
    """Return the path which would be run if the given cmd string is supplied.
    This emulates shutil.which without importing shutil."""
    if not cmd:
        return None

    # Resolve the command: if it contains a path separator, treat it literally.
    if os.sep in cmd or (hasattr(os, 'altsep') and os.altsep and os.altsep in cmd):
        if os.path.exists(cmd):
            return os.path.abspath(cmd)
        return None

    # Otherwise search PATH.
    if 'PATH' in os.environ:
        path_dirs = os.environ['PATH'].split(os.pathsep)
    else:
        path_dirs = ['/usr/bin', '/bin', '/usr/sbin', '/sbin']

    # Preserve the original command for display
    original_cmd = cmd

    # Handle extensions on Windows ( PATHEXT )
    if hasattr(os, 'PATHEXT'):
        exts = os.PATHEXT.split(os.pathsep)
    else:
        exts = ['']

    for d in path_dirs:
        # If the command already has an extension, just check it.
        if os.path.splitext(cmd)[1]:
            full_path = os.path.join(d, cmd)
            if os.path.isfile(full_path) and os.access(full_path, os.X_OK):
                return os.path.abspath(full_path)
        else:
            for ext in exts:
                full_path = os.path.join(d, cmd + ext)
                if os.path.isfile(full_path) and os.access(full_path, os.X_OK):
                    return os.path.abspath(full_path)

    return None


