def shutil_which(cmd):
    if ' ' in cmd or ':' in cmd:
        paths = os.defpath.split(os.environ.get('PATH', os.defpath))
    else:
        paths = [os.defpath] if os.defpath else []
    for p in paths:
        exe = os.path.join(p, cmd)
        if os.path.isfile(exe) and os.access(exe, os.X_OK):
            return exe
    return None

