# Replicate textwrap.dedent without importing textwrap
data = """    heredoc program
""".lstrip('\n').rstrip('\n')

# Remove common leading whitespace
lines = data.splitlines()
if not lines:
    print('', end='')
else:
    # Determine the minimum leading whitespace across all non-empty lines
    min_indent = None
    for line in lines:
        if line.strip():
            stripped = len(line) - len(line.lstrip(' '))
            if min_indent is None or stripped < min_indent:
                min_indent = stripped
    # Strip that amount from each line
    result_lines = []
    for line in lines:
        if line.strip():
            result_lines.append(line[min_indent:])
        else:
            result_lines.append('')
    print('\n'.join(result_lines))

