# Helper to collect sources as the original program would
def collect_sources():
    sources = []
    names = ['_parse_optional','_get_option_tuples','_match_arguments_partial',
             'parse_known_args','parse_args','add_argument','_add_action','_get_positional_actions']
    for n in names:
        sources.append(f"==== {n}")
        try:
            src = inspect.getsource(getattr(argparse.ArgumentParser, n))
        except Exception as src:
            src = f"[error:{src}]"
        sources.append(src)
    sources.append("==== _StoreAction")
    try:
        sources.append(inspect.getsource(argparse._StoreAction))
    except Exception as e:
        sources.append(f"[error:{e}]")
    sources.append("==== _AppendAction")
    try:
        sources.append(inspect.getsource(argparse._AppendAction))
    except Exception as e:
        sources.append(f"[error:{e}]")
    sources.append("==== _CountAction")
    try:
        sources.append(inspect.getsource(argparse._CountAction))
    except Exception as e:
        sources.append(f"[error:{e}]")
    sources.append("==== _get_action_name")
    try:
        sources.append(inspect.getsource(argparse._get_action_name))
    except Exception as e:
        sources.append(f"[error:{e}]")
    # nnm pattern access
    try:
        pat = argparse.ArgumentParser()._negative_number_matcher.pattern
    except Exception as e:
        pat = f"[error:{e}]"
    sources.append(f"==== nnm {pat}")
    return "\n".join(sources)

if __name__ == "__main__":
    # The original program used `inspect` and `argparse` imports.
    # We import them here as permitted by the runtime contract (standard library).
    import inspect
    output = collect_sources()
    sys.stdout.write(output)
    sys.exit(0)

