# This script mimics the original but avoids the format % type check.
# We determine the type name only when needed (i.e., on an actual exception).
for s, v in [('%5c', 65), ('%-5c', 65), ('%5c', 'a'), ('%c', 'a'), ('%c', ''), ('%c', 'ab'), ('%c', 65), ('%c', True), ('%c', 1.5), ('%05c', 65), ('%.2c', 65)]:
    try:
        r = repr(s % v)
    except TypeError as e:
        r = "%s: %s" % (type(e).__name__, str(e)[:40])
    print('%-6s %% %-5r -> %s' % (s, v, r))

import sys

class tag:
    def __init__(self, name):
        self.name = name
        self.entered = False

    def __enter__(self):
        if not self.entered:
            self.entered = True
            print("<" + self.name + ">")
        return self

    def __exit__(self, *args):
        if not self.entered:
            self.entered = True
            print("</" + self.name + ">")
        return False

with tag("a"):
    print("body")

