import sys

def tag(name):
    sys.stdout.write("<" + name + ">\n")
    yield
    sys.stdout.write("</" + name + ">\n")

# Manual context manager protocol to avoid the decorator
class TagManager:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        sys.stdout.write("<" + self.name + ">\n")
    def __exit__(self, exc_type, exc_val, exc_tb):
        sys.stdout.write("</" + self.name + ">\n")

with TagManager("a"):
    print("body")

import sys

class _TagManager:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print("<" + self.name + ">")
        return self
    def __exit__(self, exc_type, exc_val, exc_tb):
        print("</" + self.name + ">")
        return False

def tag(name):
    return _TagManager(name)

