# --- self-referential mutation ---
for i in range(12):
    s = set(range(i))
    if i % 4 == 0:
        s.update(s)
    elif i % 4 == 1:
        s |= s
    elif i % 4 == 2:
        # intersection_update with self is a no-op
        pass
    else:
        s.difference_update(s)
    print('S6A', i, len(s), sorted(s))
