from collections import Counter

def main():
    data = sys.stdin.read()
    counts = Counter(data)
    # Remove all whitespace characters from consideration
    non_whitespace = {ch: cnt for ch, cnt in counts.items() if not ch.isspace()}
    # Sort characters by their Unicode code point (ascending order)
    for ch in sorted(non_whitespace):
        print(f"{ch}={non_whitespace[ch]}")

if __name__ == "__main__":
    main()

import sys

def main():
    # Read all input from stdin
    text = sys.stdin.read()

    # Count occurrences of each non-whitespace character
    counts = {}
    for ch in text:
        if not ch.isspace():
            counts[ch] = counts.get(ch, 0) + 1

    # Output each distinct non-whitespace character in ascending order
    for ch in sorted(counts.keys()):
        print(f"{ch}={counts[ch]}")

if __name__ == "__main__":
    main()

import json, re, subprocess

files = subprocess.run(
    ["find", ".", "-name", "corpus.jsonl", "-o", "-name", "seed-corpus.jsonl"],
    capture_output=True, text=True
).stdout.split()

