import sys

def safe_format_char(v):
    """Compute format(v, 'c') with proper exception handling."""
    # The 'c' format specifier requires an integer or a single-character string.
    # Integers are interpreted as Unicode code points.
    # Strings longer than 1 character raise IndexError (historically ValueError in some contexts).
    try:
        return repr(format(v, 'c'))
    except Exception as e:
        return '%s: %s' % (type(e).__name__, str(e)[:50])

results = []
for v in [65, -1, 1114112, True]:
    r = safe_format_char(v)
    results.append('  format(%-8r, \'c\') -> %s' % (v, r))

# Test with a string argument that should fail
try:
    r = format('a', 'c')
    results.append("  format('a','c') -> %s" % repr(r))
except Exception as e:
    results.append("  format('a','c') -> %s: %s" % (type(e).__name__, str(e)[:50]))

sys.stdout.write('\n'.join(results) + '\n')

