import os, sys

# Simulate the needed stdlib parsing using only os.path and sys
def urlparse_(url):
    # Split scheme and rest
    scheme_end = url.find("://")
    if scheme_end == -1:
        scheme, rest = "", url
    else:
        scheme, rest = url[:scheme_end], url[scheme_end+3:]
    # Split authority (netloc) and path+query
    slash = rest.find("/")
    if slash == -1:
        netloc, pathquery = rest, ""
    else:
        netloc, pathquery = rest[:slash], rest[slash:]
    # Separate path and query
    qmark = pathquery.find("?")
    if qmark == -1:
        path, query = pathquery, ""
    else:
        path, query = pathquery[:qmark], pathquery[qmark+1:]
    # Parse query into dict of lists (like parse_qs)
    q = {}
    if query:
        for pair in query.split("&"):
            if "=" in pair:
                k, v = pair.split("=", 1)
            else:
                k, v = pair, ""
            q.setdefault(k, []).append(v)
    else:
        q = {}
    return type("P", (), {"scheme": scheme, "netloc": netloc, "path": path, "query": query})()

u = urlparse_("https://deepresearch.se/api/pub?slug=a&n=2")
print(u.netloc, u.path, u.query and parse_qs_(u.query)["slug"] or "")

