import sys, os

# Manual parsing of the URL "https://deepresearch.se/api/pub?slug=a&n=2"
# scheme: https
# netloc: deepresearch.se
# path: /api/pub
# query: slug=a&n=2

# Extract netloc: everything between "://" and the first "?"
url = "https://deepresearch.se/api/pub?slug=a&n=2"
scheme_sep = "://"
sep = url.find(scheme_sep)
if sep == -1:
    netloc = url
else:
    rest = url[sep + 3:]  # after "://"
    qmark = rest.find("?")
    if qmark == -1:
        netloc = rest
    else:
        netloc = rest[:qmark]

# Extract path: everything after netloc up to "?" or end
if qmark != -1:
    after_netloc = rest[qmark + 1:]
else:
    after_netloc = rest

question = after_netloc.find("?")
if question != -1:
    path = after_netloc[:question]
else:
    path = after_netloc

# Parse query string manually: key=value pairs separated by "&"
query = after_netloc[question + 1:] if question != -1 else ""
params = {}
if query:
    for pair in query.split("&"):
        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""
        params[k] = v

slug = params.get("slug", "")

# Output byte-identical result
print(netloc, path, slug)

import os
import sys

url = "https://deepresearch.se/api/pub?slug=a&n=2"
# Split the scheme and the rest of the URL
if "://" in url:
    _, rest = url.split("://", 1)
else:
    rest = url

# Extract the netloc (authority) path before the first '/'
slash_idx = rest.find("/")
if slash_idx != -1:
    netloc = rest[:slash_idx]
    rest_path = rest[slash_idx:]
else:
    netloc = rest
    rest_path = ""

# Extract the path part (everything after the netloc)
if rest_path.startswith("/"):
    path = rest_path
else:
    path = "/" + rest_path

# Extract the query string after the first '?'
query = ""
if "?" in path:
    path, query = path.split("?", 1)

# Parse the query string manually
params = {}
if query:
    for pair in query.split("&"):
        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""
        # Decode plus signs as spaces (standard URL query decoding)
        k = k.replace("+", " ")
        v = v.replace("+", " ")
        # Simple percent-decoding for common safe characters
        def decode(s):
            import sys
            # Use built-in bytes decode for percent-encoding
            # This handles %XX sequences
            result = []
            i = 0
            while i < len(s):
                if s[i] == '%' and i + 2 < len(s):
                    try:
                        hex_val = s[i+1:i+3]
                        result.append(chr(int(hex_val, 16)))
                        i += 3
                        continue
                    except ValueError:
                        pass
                result.append(s[i])
                i += 1
            return ''.join(result)
        k = decode(k)
        v = decode(v)
        if k in params:
            if isinstance(params[k], list):
                params[k].append(v)
            else:
                params[k] = [params[k], v]
        else:
            params[k] = v

# Output the same format as the original program
print(netloc, path, params.get("slug", [""])[0])

import os, sys, time

def run(bin, prog):
    t0 = time.perf_counter()
    pid = os.fork()
    if pid == 0:
        fd = open(os.devnull, 'w')
        os.dup2(fd, 1)
        fd.close()
        os.execv(bin, [bin, "-c", prog])
        os._exit(127)
    _, status = os.wait4(pid, 0)
    elapsed = (time.perf_counter() - t0) * 1000
    # Determine RSS without the resource module
    # If the process timed out or is still running, treat RSS as unknown (0)
    if status < 0:
        rss = 0
    else:
        exit_code = os.waitstatus_to_exitcode(status) if hasattr(os, 'waitstatus_to_exitcode') else 0
        # Use /proc/self/status on Linux to read Ru_maxrss after fork
        try:
            with open('/proc/%d/status' % pid, 'r') as f:
                for line in f:
                    if line.startswith('VmHWM:'):
                        # VmHWM is in kB
                        rss_kb = int(line.split()[1])
                        rss = rss_kb
                        break
                else:
                    rss = 0
        except Exception:
            rss = 0
    return rss, elapsed, status

PROGS = {
    "list-of-str": "a=[]\nfor i in range(300000):\n    a.append(str(i))\nprint(len(a))",
    "churn-str":   "n=0\nfor i in range(400000):\n    s='x'*20\n    n+=len(s)\nprint(n)",
    "dict-build":  "d={}\nfor i in range(200000):\n    d[str(i)]=i\nprint(len(d))",
    "churn-list":  "n=0\nfor i in range(200000):\n    a=[1,2,3,4]\n    n+=len(a)\nprint(n)",
    "big-concat":  "s=''\nfor i in range(20000):\n    s+='x'\nprint(len(s))",
}

bins = sys.argv[1:]
header = "%-12s %s" % ("case", "  ".join("%-24s" % b.split('/')[-1] for b in bins))
print(header)
for name, prog in PROGS.items():
    cells = []
    for b in bins:
        rss, ms, st = run(b, prog)
        # Convert RSS from kB to MB
        rss_mb = rss / 1024.0
        # Convert exit code properly
        if st < 0:
            exitcode = 0
        elif hasattr(os, 'waitstatus_to_exitcode'):
            exitcode = os.waitstatus_to_exitcode(st)
        else:
            # Manual extraction of exit code from wait status
            if os.name == 'posix':
                if os.WIFEXITED(st):
                    exitcode = os.WEXITSTATUS(st)
                elif os.WIFSIGNALED(st):
                    exitcode = -os.WTERMSIG(st)
                else:
                    exitcode = 0
            else:
                exitcode = 0
        cells.append("%7.1f MB %8.1f ms rc=%d" % (rss_mb, ms, exitcode))
    print("%-12s %s" % (name, "  ".join(cells)))

