import sys, os

sys.path.insert(0, os.path.dirname(os.path.realpath(__file__)))

class Date:
    """Proleptic Gregorian calendar date (year, month, day)."""
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    @classmethod
    def _days_in_month(cls, y, m):
        if m == 2:
            return 29 if cls._isleap(y) else 28
        return [0, 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m]

    @staticmethod
    def _isleap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    @classmethod
    def _days_before_year(cls, y):
        # number of days from year 0 to Jan 1 of year y
        return y * 365 + y // 4 - y // 100 + y // 400

    @classmethod
    def _days_before_month(cls, y, m):
        """Days from Jan 1 to the first day of month m (exclusive)."""
        s = 0
        for i in range(1, m):
            s += cls._days_in_month(y, i)
        return s

    @classmethod
    def from_ordinal(cls, ordinal):
        """Construct date from proleptic Gregorian ordinal (days since year 0, Jan 1 = 1)."""
        # Find year
        lo, hi = 0, 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if cls._days_before_year(mid) < ordinal:
                lo = mid + 1
            else:
                hi = mid
        y = lo - 1
        d = ordinal - cls._days_before_year(y) - 1  # days into year y (0-based)

        # Find month
        for m in range(1, 13):
            dim = cls._days_in_month(y, m)
            if d < dim:
                return Date(y, m, d + 1)
            d -= dim
        return Date(y, 12, 31)

    @classmethod
    def fromymd(cls, y, m, d):
        return cls.from_ordinal(cls._days_before_year(y) + cls._days_before_month(y, m) + d - 1)

    def __add__(self, days):
        # ordinal = days_before_year + days_before_month + day - 1
        od = self._days_before_year(self.year) + self._days_before_month(self.year, self.month) + self.day - 1 + days
        return Date.from_ordinal(od + 1)

    def __sub__(self, other):
        if isinstance(other, Date):
            return (self._days_before_year(self.year) + self._days_before_month(self.year, self.month) + self.day -
                    other._days_before_year(other.year) - other._days_before_month(other.year, other.month) - other.day)
        raise TypeError

    def __repr__(self):
        return f"{self.year:04d}-{self.month:02d}-{self.day:02d}"

