# Simulate str.casefold() and str.title() using code points
# U+00B5 MICRO SIGN (0xB5) folds to 'μ' (U+03BC), but .lower() is 'μ'
# U+00DF LATIN SMALL LETTER SHARP S (0xDF) folds to 'ss', but .upper() is 'SS'
# We incorporate the casefold/title logic directly into the filtering conditions.

def _cf(c):
    """Emulate str.casefold() return as a single character or None."""
    if c == 0x00B5:   # MICRO SIGN -> 'μ'
        return 0x03BC
    if c == 0x00DF:   # LATIN SMALL LETTER SHARP S -> 'ss' (two chars, handled separately)
        return None
    try:
        return ord(chr(c).casefold())
    except Exception:
        return None

def _title(c):
    """Emulate str.title() return as a single character or None."""
    try:
        return ord(chr(c).title())
    except Exception:
        return None

