import random

class E:
    program = "import random; random.seed(7); print(random.randrange(0,10,2))"
    tags = ()

ref = type("Result", (), {"engine": "cpython", "seed": "", "depth": 0, "stdout": "4\n", "stderr": "", "exit_code": 0})()
mp  = type("Result", (), {"engine": "lypning-mp", "seed": "", "depth": 0, "stdout": "8\n", "stderr": "", "exit_code": 0})()
t1  = type("Result", (), {"engine": "lypning",    "seed": "", "depth": 0, "stdout": "8\n", "stderr": "", "exit_code": 0})()

def is_seeded_stream(obj):
    try:
        p = getattr(obj, 'program', None)
        if p is None:
            return False
        seed_val = 7
        exec(p, {"__name__": "__main__", "seed": seed_val, "random": random})
        return True
    except Exception:
        return False

def is_run_specific(obj):
    return hasattr(obj, 'tags') and len(obj.tags) == 0

def classify(ref, candidate, engine_name, expr_obj):
    ref_stdout = ref.stdout.strip()
    cand_stdout = candidate.stdout.strip()
    if ref_stdout == cand_stdout:
        return f"verdict: {engine_name} matches reference"
    else:
        return f"verdict: {engine_name} differs from reference ({ref_stdout} vs {cand_stdout})"

print("seeded?", is_seeded_stream(E()), "run_specific?", is_run_specific(E()))
print("mp arm verdict when mp prints 8 and CPython prints 4:", classify(ref, mp, "lypning-mp", E()))
print("lypning arm verdict for the same wrong stdout:", classify(ref, t1, "lypning", E()))

