#!/usr/bin/env python3
import sys

def main():
    seconds = int(sys.stdin.read().strip())
    d = seconds // 86400
    seconds %= 86400
    h = seconds // 3600
    seconds %= 3600
    m = seconds // 60
    s = seconds % 60

    parts = []
    if d:
        parts.append(f"{d}d")
    if h:
        parts.append(f"{h}h")
    if m:
        parts.append(f"{m}m")
    if s:
        parts.append(f"{s}s")

    print(" ".join(parts))

if __name__ == "__main__":
    main()

import sys

def main():
    data = sys.stdin.read().strip()
    total = int(data)
    d = total // 86400
    total %= 86400
    h = total // 3600
    total %= 3600
    m = total // 60
    s = total % 60

    parts = []
    if d:
        parts.append(f"{d}d")
    if h:
        parts.append(f"{h}h")
    if m:
        parts.append(f"{m}m")
    if s:
        parts.append(f"{s}s")

    # Handle the case where the input is 0 seconds
    if not parts:
        print("0s")
    else:
        print(" ".join(parts))

